.scene-card{min-height:510px;display:flex;flex-direction:column;position:relative;overflow:hidden}
.scene-head{height:55px;display:flex;align-items:center;justify-content:space-between;padding:0 21px;border-bottom:1px solid #303136}
.city{position:relative;flex:1;min-height:310px;overflow:hidden;background:linear-gradient(180deg,#20232d 0%,#292b32 65%,#34353a 65%,#28292e 100%)}
.moon{position:absolute;top:32px;right:15%;width:46px;height:46px;border-radius:50%;background:#d8ff3e;box-shadow:0 0 35px #d8ff3e55;opacity:.85}
.skyline{position:absolute;bottom:34%;left:0;right:0;height:54%;display:flex;align-items:end;gap:10px;justify-content:center;opacity:.92}
.hero-silhouette{position:absolute;bottom:32%;left:25%;width:29px;height:75px;animation:patrol 3.8s ease-in-out infinite}
.city-label{position:absolute;z-index:3;top:18px;left:20px;right:20px;display:flex;justify-content:space-between;align-items:center;gap:12px;font-size:9px;letter-spacing:1.5px;color:#9b9ba0}
.mission{padding:16px 21px 18px;background:#1d1e23}
.mission-top{display:flex;justify-content:space-between;align-items:center;margin-bottom:12px}
.mission-title{font:700 13px var(--display);letter-spacing:1px;text-transform:uppercase}
.mission-time{font-size:10px;color:#aaaab0}
.mission-bottom{display:flex;justify-content:space-between;margin-top:9px;color:#909198;font-size:10px}
.toast{position:fixed;left:50%;top:24px;transform:translate(-50%,-20px);padding:12px 18px;background:var(--lime);color:#17181b;font-size:12px;font-weight:800;z-index:20;opacity:0;transition:.25s;pointer-events:none;box-shadow:4px 4px 0 #000}
.show{opacity:1;transform:translate(-50%,0)}
.city-label{display:flex;justify-content:space-between;right:19px}
.heroes-layer{position:absolute;z-index:3;left:8%;right:8%;bottom:32%;height:90px;display:flex;align-items:end;justify-content:center;gap:clamp(0px,2vw,18px);pointer-events:none}
.hero-unit{position:relative;width:38px;height:78px;flex:0 1 43px;animation:heroBob 2.8s ease-in-out infinite;animation-delay:calc(var(--n)*-.3s)}
.hero-cape{position:absolute;z-index:0;top:21px;left:-4px;width:42px;height:48px;background:var(--cape,#b43e54);clip-path:polygon(25% 0,78% 0,100% 100%,50% 75%,0 100%)}
.hero-head{position:absolute;z-index:2;top:2px;left:10px;width:20px;height:20px;border-radius:50%;display:grid;place-items:center;background:#e8c19c;border:2px solid #111;font-size:12px}
.hero-body{position:absolute;z-index:1;top:20px;left:7px;width:26px;height:37px;display:grid;place-items:center;background:var(--suit,var(--orange));border:2px solid #111;clip-path:polygon(15% 0,85% 0,100% 100%,0 100%);font-size:13px}
.hero-legs{position:absolute;top:55px;left:9px;width:24px;height:19px;border-left:7px solid #16171b;border-right:7px solid #16171b;transform:skew(-8deg)}
.hero-tag{position:absolute;top:-12px;left:50%;transform:translateX(-50%);white-space:nowrap;color:#fff;background:#15161a;padding:2px 4px;font:700 8px var(--display);letter-spacing:.5px;border:1px solid #67686c}
.hero-cape{background:#465bd1}
.hero-body{background:#5e76ff}
.hero-body{background:#9da4ae}
.hero-cape{background:#6b42bd}
.hero-body{background:#805ce0}
.hero-cape{background:#fc6536}
.hero-body{background:#ffaf37}
.heroes-overflow{align-self:center;color:var(--lime);background:#17181b;border:1px solid var(--lime);padding:4px 6px;font:800 11px var(--display)}
.vehicles-layer{position:absolute;z-index:2;bottom:30%;left:0;right:0;height:34px;pointer-events:none}
.vehicle-unit{position:absolute;left:var(--left,65%);bottom:0;font-size:29px;filter:drop-shadow(2px 2px 0 #111);animation:vehicleHover 1.5s ease-in-out infinite alternate}
.jet{bottom:42px;font-size:31px;animation:vehicleFly 7s linear infinite}
.ship{bottom:75px;font-size:36px;animation:vehicleFly 12s linear infinite}
.vehicle-count{position:absolute;top:-8px;right:-11px;background:var(--lime);color:#17181b;border-radius:10px;padding:1px 5px;font:800 9px var(--body)}
.boss-panel{display:none;position:absolute;z-index:8;inset:50px 12px auto;padding:12px 15px 11px;background:#17171bf2;border:2px solid var(--orange);box-shadow:5px 5px 0 #080809;text-align:center;max-width:290px;margin:auto;left:0;right:0}
.active{display:block;animation:bossIn .3s ease}
.boss-label{font:800 9px var(--display);letter-spacing:1.6px;color:var(--orange)}
.boss-face{font-size:43px;line-height:1.15;filter:drop-shadow(3px 3px 0 #050505);animation:bossPulse .7s ease-in-out infinite alternate}
.boss-name{font:900 15px var(--display);letter-spacing:1px}
.boss-health{height:8px;background:#39393d;border:1px solid #777;margin:7px 0 4px}
.boss-meta{display:flex;justify-content:space-between;font-size:9px;font-weight:800;color:#d4d4d8}
.boss-tip{margin-top:7px;font:800 9px var(--display);letter-spacing:1px;color:var(--lime)}
.mission{border-top:1px solid var(--orange)}
.boss-mode{background:#ff3b4e;border-color:#ffb1a3;animation:bossButton .6s infinite alternate}
.mission-fist{color:var(--orange);margin-right:5px}
.heroes-layer{height:108px;gap:clamp(2px,2.4vw,22px)}
.hero-unit{width:58px;height:96px;flex:0 1 58px;filter:drop-shadow(0 5px 5px #0008)}
.hero-cape{top:25px;left:-4px;width:62px;height:58px;clip-path:polygon(24% 0,76% 0,100% 100%,50% 77%,0 100%);filter:drop-shadow(0 0 5px var(--glow,#5ad9ff55))}
.hero-head{top:5px;left:17px;width:25px;height:25px;background:linear-gradient(145deg,#ffe2c0,#b97954);border:2px solid #14151a;box-shadow:inset 0 -5px 0 #0002}
.hero-body{top:27px;left:11px;width:38px;height:43px;border:2px solid #15161a;clip-path:polygon(21% 0,79% 0,100% 100%,0 100%);font-size:15px;text-shadow:0 1px 3px #000;box-shadow:inset 0 0 0 2px #ffffff38}
.hero-legs{top:67px;left:17px;width:26px;height:23px;border-left:9px solid var(--boots,#18191e);border-right:9px solid var(--boots,#18191e);filter:drop-shadow(0 0 2px var(--glow,#000))}
.hero-tag{top:-3px;font-size:9px;padding:2px 6px;border-color:var(--trim,#777);box-shadow:0 0 9px color-mix(in srgb,var(--glow,#000) 50%,transparent)}
.hero-head{z-index:2}
.hero-cape{clip-path:polygon(20% 0,80% 0,100% 100%,50% 72%,0 100%)}
.hero-head{border-radius:8px 8px 12px 12px;background:linear-gradient(135deg,#d9f6f7,#4d8290)}
.hero-cape{left:4px;width:50px;clip-path:polygon(15% 0,85% 0,100% 100%,50% 82%,0 100%);transform:skewY(-12deg)}
.hero-head{border-radius:40% 40% 15% 15%;background:linear-gradient(135deg,#20c9ff,#075078)}
.hero-body{background:linear-gradient(100deg,#123a54 0 24%,#1dc4ee 25% 35%,#145579 36% 70%,#1dc4ee 71% 80%,#123a54 81%)}
.hero-cape{width:66px;left:-8px;clip-path:polygon(12% 0,88% 0,100% 100%,50% 78%,0 100%)}
.hero-body{left:7px;width:44px;background:linear-gradient(90deg,#617482,#c4d2da 25%,#70818c 50%,#dce5e8 75%,#5a6d78);clip-path:polygon(12% 0,88% 0,100% 100%,0 100%)}
.hero-head{border-radius:7px 7px 12px 12px;background:linear-gradient(135deg,#f1d6b7,#94745e)}
.hero-cape{top:19px;height:68px;clip-path:polygon(50% 0,90% 12%,100% 100%,50% 85%,0 100%,10% 12%)}
.hero-head{top:2px;width:30px;height:29px;left:14px;border:0;border-radius:50% 50% 35% 35%;background:linear-gradient(135deg,#39216a,#120c24)}
.hero-body{background:linear-gradient(90deg,#2c1a55,#8b5ce1 45%,#3b246a)}
.hero-cape{top:20px;height:68px;clip-path:polygon(25% 0,75% 0,100% 100%,68% 82%,50% 100%,32% 82%,0 100%);background:linear-gradient(180deg,#ffcb3d,#f14d24 58%,#8d231c)}
.hero-head{border-radius:45% 45% 35% 35%;background:linear-gradient(135deg,#ffe1ad,#d78043)}
.hero-body{background:linear-gradient(100deg,#9b2c21,#ff7c24 48%,#c83720)}
.heroes-overflow{display:none}
.scene-card{min-height:400px}
.city{min-height:270px}

